 28	export type HookFetchInit = {
 29	  method?: string;
 30	  headers?: Record<string, string>;
 31	  body?: string;
 32	};
 33	
 34	export type HookFetchResponse = {
 35	  status: number;
 36	  ok: boolean;
 37	  text: string;
 38	};
