 43	export type HookConfig = CompactOptions & {
 44	  apiKey?: string;
 45	  compactAtPercent: number;
 46	  minReductionRatio: number;
 47	  model: string;
 48	};
 49	
 50	function optionNumber(options: PluginOptions, key: string, fallback: number): number {
 51	  const value = options[key];
 52	  return typeof value === 'number' && Number.isFinite(value) ? value : fallback;
 53	}
 54	
 55	function optionString(options: PluginOptions, key: string): string | undefined {
 56	  const value = options[key];
 57	  return typeof value === 'string' && value.length > 0 ? value : undefined;
 58	}
 59	
 60	/** Reads the plugin's `userConfig` values; anything missing takes the defaults. */
 61	export function resolveHookConfig(options: PluginOptions): HookConfig {
 62	  const numbers: Partial<Omit<CompactOptions, 'goal'>> = {};
 63	  for (const key of [
 64	    'keepThreshold',
 65	    'preserveRecentMessages',
 66	    'maxStateTokens',
 67	    'maxRequestTokens',
 68	    'truncateHeadChars',
 69	  ] as const) {
 70	    const value = options[key];
 71	    if (typeof value === 'number' && Number.isFinite(value)) numbers[key] = value;
 72	  }
 73	  const config: HookConfig = {
 74	    ...numbers,
 75	    compactAtPercent: optionNumber(options, 'compactAtPercent', HOOK_DEFAULTS.compactAtPercent),
 76	    minReductionRatio: optionNumber(
 77	      options,
 78	      'minReductionRatio',
 79	      HOOK_DEFAULTS.minReductionRatio,
 80	    ),
 81	    model: optionString(options, 'model') ?? HOOK_DEFAULTS.model,
 82	  };
 83	  const apiKey = optionString(options, 'apiKey');
 84	  if (apiKey) config.apiKey = apiKey;
 85	  const goal = optionString(options, 'goal');
 86	  if (goal) config.goal = goal;
 87	  return config;
 88	}
