 90	/** A `JevAsker` over the engine's `$.http.fetch`. */
 91	export function jevAsker(fetchFn: HookFetch, apiKey: string, model: string): JevAsker {
 92	  return {
 93	    async ask(state, questions) {
 94	      const request = buildJevRequest({ apiKey, model }, state, questions);
 95	      const response = await fetchFn(request.url, {
 96	        method: request.method,
 97	        headers: request.headers,
 98	        body: request.body,
 99	      });
100	      return parseJevResponse(response.status, response.ok, response.text);
101	    },
102	  };
103	}
