105	function toolUseSummary(tool: ToolUse): ToolUseSummary {
106	  const summary: ToolUseSummary = {
107	    tool_use_id: tool.tool_use_id,
108	    tool: tool.tool,
109	    input: tool.input,
110	  };
111	  if (tool.text !== undefined) summary.text = tool.text;
112	  if (tool.isError) summary.isError = true;
113	  return summary;
114	}
