124	/**
125	 * Maps the library's output back onto session messages. Whatever came back
126	 * unchanged (a message, a tool use, a tool result) is the engine's own object,
127	 * handle included; anything rebuilt is a fresh message without a handle, so the
128	 * engine takes the edited content instead of its original.
129	 */
130	export function toSessionMessages(
131	  input: readonly SessionMessage[],
132	  output: readonly Message[],
133	): SessionMessage[] {
134	  const messages = new Map<Message, SessionMessage>();
135	  const uses = new Map<ToolUse, ToolUseSummary>();
136	  const results = new Map<ToolResult, ToolResultSummary>();
137	  for (const message of input) {
138	    messages.set(message, message);
139	    for (const tool of message.toolUses) uses.set(tool, tool);
140	    for (const result of message.toolResults ?? []) results.set(result, result);
141	  }
142	  return output.map((message) => {
143	    const own = messages.get(message);
144	    if (own) return own;
145	    const rebuilt: SessionMessage = {
146	      role: message.role,
147	      text: message.text,
148	      toolUses: message.toolUses.map((tool) => uses.get(tool) ?? toolUseSummary(tool)),
149	    };
150	    if (message.toolResults && message.toolResults.length > 0) {
151	      rebuilt.toolResults = message.toolResults.map(
152	        (result) => results.get(result) ?? toolResultSummary(result),
153	      );
154	    }
155	    return rebuilt;
156	  });
157	}
