164	/** Runs the library over a session transcript; throws when the key is missing or Jev fails. */
165	export async function compactSession(
166	  messages: readonly SessionMessage[],
167	  config: HookConfig,
168	  fetchFn: HookFetch,
169	): Promise<SessionCompaction> {
170	  if (!config.apiKey) throw new Error('TYPESAFE_API_KEY is not configured');
171	  const result = await compact(messages, jevAsker(fetchFn, config.apiKey, config.model), config);
172	  return { result, messages: toSessionMessages(messages, result.messages) };
173	}
