175	function percent(ratio: number): string {
176	  return `${Math.round(ratio * 100)}%`;
177	}
178	
179	export function summarize(result: CompactResult): string {
180	  const { stats } = result;
181	  const parts = [
182	    stats.kept > 0 ? `${stats.kept} kept` : '',
183	    stats.resultsDropped > 0 ? `${stats.resultsDropped} results truncated` : '',
184	    stats.callsDropped > 0 ? `${stats.callsDropped} call_dropped` : '',
185	    stats.pinned > 0 ? `${stats.pinned} pinned` : '',
186	  ].filter(Boolean);
187	  return `${percent(reductionRatio(result))} reduction; ${
188	    parts.join(', ') || 'no tool calls'
189	  }; state ~${stats.stateTokens} tokens (${stats.stateStage}) in ${stats.requests} request(s)`;
190	}
191	
192	const UI_LOG_MAX_CHARS = 4096;
193	
194	export function decisionLog(result: CompactResult): string {
195	  return result.decisions
196	    .filter((d) => d.reason !== 'pinned')
197	    .map(
198	      (d) =>
199	        `${d.id}:${d.tool}:${d.action}/call=${d.keepCall.toFixed(2)}/result=${d.keepResult.toFixed(2)}`,
200	    )
201	    .join(' ');
202	}
203	
204	export function decisionLogLines(
205	  result: CompactResult,
206	  maxChars: number = UI_LOG_MAX_CHARS,
207	): string[] {
208	  const entries = decisionLog(result).split(' ').filter(Boolean);
209	  if (entries.length === 0) return ['decisions: (none)'];
210	  const chunks: string[] = [];
211	  let current = '';
212	  for (const entry of entries) {
213	    const next = current ? `${current} ${entry}` : entry;
214	    if (current && next.length > maxChars - 24) {
215	      chunks.push(current);
216	      current = entry;
217	    } else current = next;
218	  }
219	  chunks.push(current);
220	  return chunks.map((chunk, index) =>
221	    chunks.length === 1
222	      ? `decisions: ${chunk}`
223	      : `decisions (${index + 1}/${chunks.length}): ${chunk}`,
224	  );
225	}
