227	async function getApiKey(
228	  $: {
229	    env: { get: (name: string) => Promise<string | undefined> };
230	    settings: { read: () => Promise<Readonly<Record<string, unknown>>> };
231	  },
232	  config: HookConfig,
233	): Promise<string | undefined> {
234	  if (config.apiKey) return config.apiKey;
235	  const fromEnv = await $.env.get('TYPESAFE_API_KEY');
236	  if (fromEnv) return fromEnv;
237	  const settings = await $.settings.read();
238	  const env = settings['env'];
239	  if (env && typeof env === 'object') {
240	    const value = (env as Record<string, unknown>)['TYPESAFE_API_KEY'];
241	    if (typeof value === 'string' && value) return value;
242	  }
243	  return undefined;
244	}
