246	function notify(
247	  $: {
248	    ui: {
249	      log: (text: string) => void;
250	      toast: (text: string, options?: { timeoutMs?: number }) => void;
251	    };
252	  },
253	  text: string,
254	): void {
255	  $.ui.log(text);
256	  $.ui.toast(text, { timeoutMs: 15_000 });
257	}
