259	export const register: Register = (on: On, options: PluginOptions) => {
260	  const configured = resolveHookConfig(options);
261	  let compacting = false;
262	
263	  on('session.compact', async ($, event, next) => {
264	    try {
265	      const config = { ...configured, apiKey: await getApiKey($, configured) };
266	      const { result, messages } = await compactSession(event.messages, config, async (url, init) => {
267	        const response = await $.http.fetch(url, init);
268	        return { status: response.status, ok: response.ok, text: response.text };
269	      });
270	      for (const line of decisionLogLines(result)) $.ui.log(line);
271	      if (reductionRatio(result) < config.minReductionRatio) {
272	        notify(
273	          $,
274	          `fallback to built-in summary (below ${percent(config.minReductionRatio)} minimum: ${summarize(result)})`,
275	        );
276	        return next(event);
277	      }
278	      notify(
279	        $,
280	        `kept ${messages.length}/${event.messages.length} messages, no summary (${summarize(result)})`,
281	      );
282	      return { messages };
283	    } catch (error) {
284	      notify(
285	        $,
286	        `fallback to built-in summary (${error instanceof Error ? error.message : String(error)})`,
287	      );
288	      return next(event);
289	    }
290	  });
291	
292	  on('turn.complete', async ($, event: TurnCompleteInput, next) => {
293	    if (compacting) return next(event);
294	    try {
295	      const { context } = await $.session.usage();
296	      if ((context.percent ?? 0) < configured.compactAtPercent) return next(event);
297	      compacting = true;
298	      await $.session.compact();
299	    } catch (error) {
300	      $.ui.log(
301	        `auto-compact skipped (${error instanceof Error ? error.message : String(error)})`,
302	      );
303	    } finally {
304	      compacting = false;
305	    }
306	    return next(event);
307	  });
308	};
