 1	import type { JevAnswer, JevQuestions, JevResponse, JevState } from './types.js';
 2	
 3	export const SYSTEM_ONE_URL = 'https://api.typesafe.ai/v1/systemone';
 4	export const DEFAULT_MODEL = 'jev-latest';
 5	
 6	export interface JevRequest {
 7	  url: string;
 8	  method: 'POST';
 9	  headers: Record<string, string>;
10	  body: string;
11	}
12	
13	/** The HTTP request for one Jev call, for any fetch-like transport. */
14	export function buildJevRequest(
15	  params: {
16	    apiKey: string;
17	    model?: string;
18	    baseUrl?: string;
19	  },
20	  state: JevState,
21	  questions: JevQuestions,
22	): JevRequest {
23	  return {
24	    url: params.baseUrl ?? SYSTEM_ONE_URL,
25	    method: 'POST',
26	    headers: {
27	      authorization: `Bearer ${params.apiKey}`,
28	      'content-type': 'application/json',
29	    },
30	    body: JSON.stringify({
31	      model: params.model ?? DEFAULT_MODEL,
32	      state,
33	      questions,
34	    }),
35	  };
36	}
37	
38	/** Validates a Jev response body; throws on anything but an `answers` object. */
39	export function parseJevResponse(
40	  status: number,
41	  ok: boolean,
42	  text: string,
43	): JevResponse {
44	  if (!ok) {
45	    throw new Error(`Jev request failed (${status}): ${text.slice(0, 200)}`);
46	  }
47	  let parsed: unknown;
48	  try {
49	    parsed = JSON.parse(text);
50	  } catch {
51	    throw new Error('Jev returned malformed JSON');
52	  }
53	  if (
54	    parsed === null ||
55	    typeof parsed !== 'object' ||
56	    !('answers' in parsed) ||
57	    parsed.answers === null ||
58	    typeof parsed.answers !== 'object'
59	  ) {
60	    throw new Error('Jev response is missing answers');
61	  }
62	  return parsed as JevResponse;
63	}
64	
65	/** The `noul` probability of one answer; throws when it is not there. */
66	export function noulAnswer(
67	  answers: Record<string, JevAnswer>,
68	  name: string,
69	): number {
70	  const answer = answers[name];
71	  if (
72	    !answer ||
73	    !('noul' in answer) ||
74	    typeof answer.noul !== 'number' ||
75	    !Number.isFinite(answer.noul)
76	  ) {
77	    throw new Error(`Invalid Jev answer for ${name}`);
78	  }
79	  return answer.noul;
80	}
