  3	/**
  4	 * A tool_use block of an assistant message. `text` and `isError` mirror the
  5	 * outcome once the transcript holds it (Claude Code attaches them).
  6	 */
  7	export interface ToolUse {
  8	  tool_use_id: string;
  9	  tool: string;
 10	  input: Record<string, unknown>;
 11	  text?: string;
 12	  isError?: boolean;
 13	}
