 33	/** A tool call paired with its result by `tool_use_id`. */
 34	export interface ToolCall {
 35	  /** Short id used in the Jev state and question names (`t1`, `t2`, ...). */
 36	  id: string;
 37	  tool_use_id: string;
 38	  tool: string;
 39	  input: Record<string, unknown>;
 40	  /** Index of the message holding the tool_use block. */
 41	  callIndex: number;
 42	  /** Index of the message holding the tool_result block. */
 43	  resultIndex: number;
